471	
472	            // 2) 송장 정보 업데이트 (택배사, 송장번호)
473	            shipment.updateTrackingInfo(courier, trackingNumber);
474	            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);
475	
476	            // 3) CJ대한통운 조회로 현재 상태 확인
477	            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
478	            ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
479	
480	            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
481	
482	            // 4) 상태에 따른 처리
483	            if (newStatus == ShipmentStatus.DELIVERED) {
