    77	                .skipLimit(SKIP_LIMIT)
    78	                .listener(shipmentSkipListener())
    79	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
    80	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
    81	                .build();
    82	    }
